import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
dfs = {}
for i in range(1, 8):
    try:
        df = pd.read_csv(f'experiment_{i}_csv')
        dfs[i] = df
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(df.columns)}")
        print(df.describe().round(2))
    except Exception as e:
        print(f"Error loading exp {i}: {e}")

# Look for throughput across experiments
throughputs = []
for i, df in dfs.items():
    if 'JobThroughput' in df.columns:
        throughputs.append((i, df['JobThroughput'].mean(), df['JobThroughput'].std()))

print("\n=== THROUGHPUT SUMMARY ===")
for exp, mean, std in throughputs:
    print(f"Exp {exp}: mean={mean:.2f}, std={std:.2f}, n={len(dfs[exp])}")

# Check correlations in each experiment that has multiple variables
for i, df in dfs.items():
    numeric_cols = df.select_dtypes(include=[np.number]).columns
    if len(numeric_cols) > 1:
        print(f"\n=== Experiment {i} correlations ===")
        corr = df[numeric_cols].corr(numeric_only=True).round(3)
        print(corr)

